add_action( 'woocommerce_register_form_tag', 'perfectpixel_registration_form_enctype' );
add_action( 'woocommerce_register_form', 'perfectpixel_registration_file_field' );
add_filter( 'woocommerce_registration_errors', 'perfectpixel_registration_file_validate', 10, 3 );
add_action( 'woocommerce_created_customer', 'perfectpixel_registration_file_save' );
add_action( 'show_user_profile', 'perfectpixel_registration_file_profile' );
add_action( 'edit_user_profile', 'perfectpixel_registration_file_profile' );

function perfectpixel_registration_form_enctype() {
	echo 'enctype="multipart/form-data"';
}

function perfectpixel_registration_file_field() {
	$required = 'yes' === '{{registration_file_required}}';
	echo '<p class="form-row form-row-wide"><label for="perfectpixel_reg_file">' . esc_html( '{{registration_file_label}}' ) . ( $required ? ' <span class="required">*</span>' : '' ) . '</label>';
	echo '<input type="file" id="perfectpixel_reg_file" name="perfectpixel_reg_file" accept=".jpg,.jpeg,.png,.pdf"' . ( $required ? ' required' : '' ) . '></p>';
}

function perfectpixel_registration_file_ok() {
	if ( empty( $_FILES['perfectpixel_reg_file']['name'] ) ) {
		return null; // Nothing uploaded.
	}
	$file  = $_FILES['perfectpixel_reg_file'];
	$check = wp_check_filetype_and_ext( $file['tmp_name'], $file['name'], array( 'jpg|jpeg' => 'image/jpeg', 'png' => 'image/png', 'pdf' => 'application/pdf' ) );
	$max   = max( 1, (float) '{{registration_file_max_mb}}' ) * MB_IN_BYTES;
	return UPLOAD_ERR_OK === $file['error'] && $check['ext'] && $file['size'] <= $max;
}

function perfectpixel_registration_file_validate( $errors, $username, $email ) {
	$ok = perfectpixel_registration_file_ok();
	if ( false === $ok || ( null === $ok && 'yes' === '{{registration_file_required}}' ) ) {
		$errors->add( 'perfectpixel_reg_file', '{{registration_file_error}}' );
	}
	return $errors;
}

function perfectpixel_registration_file_save( $user_id ) {
	if ( true !== perfectpixel_registration_file_ok() ) {
		return;
	}
	require_once ABSPATH . 'wp-admin/includes/file.php';
	require_once ABSPATH . 'wp-admin/includes/media.php';
	require_once ABSPATH . 'wp-admin/includes/image.php';
	$attachment_id = media_handle_upload( 'perfectpixel_reg_file', 0, array(), array( 'test_form' => false, 'mimes' => array( 'jpg|jpeg' => 'image/jpeg', 'png' => 'image/png', 'pdf' => 'application/pdf' ) ) );
	if ( ! is_wp_error( $attachment_id ) ) {
		update_user_meta( $user_id, 'perfectpixel_registration_file', (int) $attachment_id );
	}
}

function perfectpixel_registration_file_profile( $user ) {
	$attachment_id = (int) get_user_meta( $user->ID, 'perfectpixel_registration_file', true );
	if ( $attachment_id && current_user_can( 'edit_users' ) ) {
		echo '<h2>Αρχείο εγγραφής</h2><p><a href="' . esc_url( wp_get_attachment_url( $attachment_id ) ) . '" target="_blank" rel="noopener">' . esc_html( basename( get_attached_file( $attachment_id ) ) ) . '</a></p>';
	}
}
